/* =====================================================================
   מבנה התוכן — כאן מוסיפים נושאים, תתי־נושאים ומקורות השראה.

   TOPICS = [ נושא ]
     נושא   = { key, name, hue, blurb, subs: [ תת־נושא ] }
     תת־נושא = { key, name, blurb, sources: [ מקור השראה ] }   // sources ריק = "בהכנה"
     מקור   = { key, kingdom, hue, name, taxon, strategy,
                // kingdom חייב להיות אחד מ: "animal" (בעלי חיים) | "plant" (צמחים) | "mineral" (דומם).
                // כל תת־נושא מוצג תמיד בשלוש הממלכות בסדר הזה; ממלכה חסרה מוצגת כמשבצת ריקה.
                mech: { img, title, line, body, facts:[[שם,ערך]] },   // המנגנון בטבע
                app:  { img, title, line, body, facts:[[שם,ערך]] },   // היישום בבנייה
                bridge, note, refs:[] }

   img מקבל data:image/jpeg;base64,... או נתיב יחסי לקובץ תמונה.
   ===================================================================== */

